  return Response.json({ ok: true }, { status: 201 });
}

import { ensureDatabase } from "../../../db";
import { MAX_CONTEXT_LENGTH, MAX_TASK_LENGTH } from "../../../lib/task-submission";

function isSameOrigin(request: Request) {
  const origin = request.headers.get("origin");
  return !origin || origin === new URL(request.url).origin;
}

function escapeHtml(value: string) {
  return value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[character] ?? character);
}

function taskCard(task: string) {
  const safeTask = escapeHtml(task);
  return `<style>
    :host{display:block;font-family:system-ui,sans-serif;color:#202124}
    article{padding:28px}p{color:#61656a}h1{font-size:28px;line-height:1.3;white-space:pre-wrap;overflow-wrap:anywhere}
  </style><article><p>Task queued</p><h1>${safeTask}</h1></article>`;
}

export async function POST(request: Request) {
  if (!isSameOrigin(request)) return Response.json({ error: "Blocked origin" }, { status: 403 });
  const payload = (await request.json()) as { task?: string; context?: string };
  const task = payload.task?.trim() ?? "";
  const context = payload.context?.trim() ?? "";
  if (!task || task.length > MAX_TASK_LENGTH) return Response.json({ error: "Task must be 1–5000 characters." }, { status: 400 });
  if (context.length > MAX_CONTEXT_LENGTH) return Response.json({ error: "Context must be at most 40000 characters." }, { status: 400 });

  const db = await ensureDatabase();
  const latestContext = await db.prepare("SELECT text FROM contexts ORDER BY id DESC LIMIT 1").first<{ text: string }>();
  if (context && context !== latestContext?.text) {
    await db.prepare("INSERT INTO contexts (text) VALUES (?)").bind(context).run();
  }

  const taskKey = `user-task-${crypto.randomUUID()}`;
  const headline = task.replace(/\s+/g, " ").slice(0, 180);
  const agentContext = JSON.stringify({
    kind: "user_task",
    task,
    generalContext: context || latestContext?.text || "",
    source: "Agency New Task",
  });
  const idea = await db.prepare("INSERT INTO ideas (project, category, headline, why_matters, impact, finished_work, primary_action, secondary_action, external_action, card_html, agent_context, score, rise_reach, rise_impact, rise_strategic_fit, rise_ease, source_label, source_url, agent_name, preview_kind, preview_title, preview_body, preview_asset, dedupe_key, status) VALUES ('Agency', 'Quick task', ?, '', '', '', '', '', '', ?, ?, 0, 0, 0, 0, 0, 'User-created task', '', 'Agency · Task Runner', 'html', '', '', '', ?, 'working') RETURNING id, project, category, headline, card_html AS cardHtml, agent_context AS agentContext, source_label AS sourceLabel, source_url AS sourceUrl, dedupe_key AS dedupeKey")
    .bind(headline, taskCard(task), agentContext, taskKey).first();
  if (!idea?.id) return Response.json({ error: "Task card could not be created." }, { status: 500 });

  const cardContext = JSON.stringify({
    idea,
    task: { request: task, generalContext: context || latestContext?.text || "", source: "New Task" },
    click: { action: "task", label: "New Task", instruction: task, note: "" },
  });
  const job = await db.prepare("INSERT INTO agent_jobs (idea_id, action, button_label, instruction, user_feedback, card_context) VALUES (?, 'task', 'New Task', ?, '', ?) RETURNING id")
    .bind(idea.id, task, cardContext).first();
  if (!job?.id) return Response.json({ error: "Task could not be queued." }, { status: 500 });

  return Response.json({ ok: true, ideaId: idea.id, jobId: job.id }, { status: 201 });
}

import { env } from "cloudflare:workers";
import { ensureDatabase } from "../../../db";
import { estimateDecisionTime } from "../../../lib/decision-time";
import { calculateRiseScore, normalizeRise, type RiseBreakdown } from "../../../lib/rise";
import { BLOCKED_CARD_UPDATE_SQL, cardIngestMode } from "../../../lib/blocked-card";

type NewCard = {
  project?: string;
  category?: string;
  headline?: string;
  cardHtml?: string;
  agentContext?: string | Record<string, unknown>;
  score?: number;
  rise?: Partial<RiseBreakdown>;
  effortSeconds?: number;
  effortReason?: string;
  decisionEstimateSeconds?: number;
  decisionEstimateReason?: string;
  sourceLabel?: string;
  sourceUrl?: string;
  agentName?: string;
  dedupeKey?: string;
  blockedJobId?: number;
  expectedVersion?: number;
};

const MAX_CARD_HTML_LENGTH = 250_000;

function canIngest(request: Request) {
  const origin = request.headers.get("origin");
  if (origin) return origin === new URL(request.url).origin;
  const url = new URL(request.url);
  const loopback = url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "[::1]";
  if (loopback && request.headers.get("x-radar-local-agent") === "1") return true;
  const expected = (env as unknown as { RADAR_AGENT_KEY?: string }).RADAR_AGENT_KEY;
  return Boolean(expected) && request.headers.get("x-radar-agent-key") === expected;
}

function unsafeHtml(html: string) {
  return /<\s*(script|iframe|object|embed|form|meta|base|link|svg|math|a)\b/i.test(html)
    || /\son[a-z]+\s*=/i.test(html)
    || /javascript\s*:/i.test(html)
    || /@import\b/i.test(html)
    || /url\s*\(\s*["']?(?:https?:)?\/\//i.test(html)
    || /\s(?:src|poster|srcset)\s*=\s*["'](?:https?:)?\/\//i.test(html);
}

export async function POST(request: Request) {
  if (!canIngest(request)) return Response.json({ error: "Missing agent key" }, { status: 401 });
  const card = (await request.json()) as NewCard;
  const project = card.project?.trim() ?? "";
  const category = card.category?.trim() ?? "";
  const headline = card.headline?.trim() ?? "";
  const cardHtml = card.cardHtml?.trim() ?? "";
  const dedupeKey = card.dedupeKey?.trim() ?? "";
  if (!project || !category || !headline || !dedupeKey || cardHtml.length < 80 || cardHtml.length > MAX_CARD_HTML_LENGTH) {
    return Response.json({ error: "Card needs project, category, headline, dedupeKey, and 80–250000 characters of HTML." }, { status: 400 });
  }
  if (unsafeHtml(cardHtml)) return Response.json({ error: "Card HTML contains an unsafe element or attribute." }, { status: 400 });
  const ingestMode = cardIngestMode(cardHtml, card.blockedJobId, card.expectedVersion);
  if (!ingestMode) {
    return Response.json({ error: "A suggestion needs a meaningful next-step button. A blocked replacement instead needs blockedJobId, expectedVersion, a data-radar-state='blocked' marker, and no Do action." }, { status: 400 });
  }
  const context = typeof card.agentContext === "string" ? card.agentContext : JSON.stringify(card.agentContext ?? {});
  if (context.length > 100_000) return Response.json({ error: "Agent context is too large." }, { status: 400 });
  const rise = normalizeRise(card.rise, card.score);
  if (!rise) {
    return Response.json({ error: "Every card needs a RISE estimate: reach, impact, strategicFit, and ease from 0–25." }, { status: 400 });
  }
  const score = calculateRiseScore(rise);
  const decisionEstimate = estimateDecisionTime({
    category,
    headline,
    cardHtml,
    agentContext: context,
    decisionEstimateMs: Number(card.effortSeconds ?? card.decisionEstimateSeconds ?? 0) * 1_000,
    decisionEstimateReason: card.effortReason ?? card.decisionEstimateReason ?? "",
  });
  const db = await ensureDatabase();
  if (ingestMode === "blocked") {
    const result = await db.prepare(BLOCKED_CARD_UPDATE_SQL)
      .bind(headline, cardHtml, context, dedupeKey, card.expectedVersion, card.blockedJobId).first();
    if (!result) return Response.json({ error: "Blocked replacement is stale or does not match the card's latest failed/blocked job." }, { status: 409 });
    // Preserve status, ranking, timestamps, and the terminal blocked outcome.
    return Response.json({ ok: true, idea: result, blocked: true }, { status: 201 });
  }
  const result = await db.prepare("INSERT INTO ideas (project, category, headline, why_matters, impact, finished_work, primary_action, secondary_action, external_action, card_html, agent_context, score, rise_reach, rise_impact, rise_strategic_fit, rise_ease, decision_estimate_ms, decision_estimate_reason, source_label, source_url, agent_name, preview_kind, preview_title, preview_body, preview_asset, dedupe_key) VALUES (?, ?, ?, '', '', '', '', '', '', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'html', '', '', '', ?) ON CONFLICT(dedupe_key) DO UPDATE SET project=excluded.project, category=excluded.category, headline=excluded.headline, card_html=excluded.card_html, agent_context=excluded.agent_context, score=excluded.score, rise_reach=excluded.rise_reach, rise_impact=excluded.rise_impact, rise_strategic_fit=excluded.rise_strategic_fit, rise_ease=excluded.rise_ease, decision_estimate_ms=excluded.decision_estimate_ms, decision_estimate_reason=excluded.decision_estimate_reason, source_label=excluded.source_label, source_url=excluded.source_url, agent_name=excluded.agent_name, version=ideas.version+1, status='new', created_at=CURRENT_TIMESTAMP RETURNING id, version")
    .bind(project, category, headline, cardHtml, context, score, rise.reach, rise.impact, rise.strategicFit, rise.ease, decisionEstimate.estimatedMs ?? 0, decisionEstimate.reason, card.sourceLabel?.trim() ?? "", card.sourceUrl?.trim() ?? "", card.agentName?.trim() ?? "Agency", dedupeKey).first();
  // A replacement card answers a blocked job: mark that job as review so the
  // startup reconcile does not drag the fresh card back to Working forever.
  const replacedId = (result as { id?: number } | null)?.id;
  if (replacedId) {
    await db.prepare(`
      UPDATE agent_jobs SET ticket_outcome = 'review', updated_at = CURRENT_TIMESTAMP
      WHERE ticket_outcome = 'blocked' AND status = 'failed'
        AND id = (SELECT MAX(id) FROM agent_jobs WHERE idea_id = ?)
    `).bind(replacedId).run();
  }
  return Response.json({ ok: true, idea: result }, { status: 201 });
}

import { env } from "cloudflare:workers";
import { ensureDatabase } from "../../../db";
import { canUpdateJob, ideaStatusForOutcome, jobLeaseWindow, MAX_CONCURRENT_JOBS, resolveTicketOutcome, type StoredJobStatus, type TicketOutcome } from "../../../lib/job-lifecycle";

function canUseQueue(request: Request) {
  const origin = request.headers.get("origin");
  if (origin) return origin === new URL(request.url).origin;
  const url = new URL(request.url);
  const loopback = url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "[::1]";
  if (loopback && request.headers.get("x-radar-local-agent") === "1") return true;
  const expected = (env as unknown as { RADAR_AGENT_KEY?: string }).RADAR_AGENT_KEY;
  return Boolean(expected) && request.headers.get("x-radar-agent-key") === expected;
}

export async function GET(request: Request) {
  if (!canUseQueue(request)) return Response.json({ error: "Missing agent key" }, { status: 401 });
  const db = await ensureDatabase();
  const leaseWindow = jobLeaseWindow();
  const jobs = await db.prepare(`
    WITH latest_jobs AS (
      SELECT job.*
      FROM agent_jobs job
      WHERE NOT EXISTS (
        SELECT 1 FROM agent_jobs newer
        WHERE newer.idea_id = job.idea_id AND newer.id > job.id
      )
    ), capacity AS (
      SELECT MAX(0, ? - COUNT(*)) AS slots
      FROM latest_jobs
      WHERE status = 'running' AND updated_at > datetime('now', ?)
    )
    SELECT
      id,
      idea_id AS ideaId,
      action,
      button_label AS buttonLabel,
      instruction,
      user_feedback AS userFeedback,
      card_context AS cardContext,
      ticket_outcome AS ticketOutcome,
      'queued' AS status,
      status = 'running' AS reclaimed,
      created_at AS createdAt,
      updated_at AS updatedAt
    FROM latest_jobs
    WHERE status = 'queued'
      OR (status = 'running' AND updated_at <= datetime('now', ?))
    ORDER BY status = 'running' ASC, id ASC
    LIMIT (SELECT slots FROM capacity)
  `).bind(MAX_CONCURRENT_JOBS, leaseWindow, leaseWindow).all<{ id: number; ideaId: number } & Record<string, unknown>>();
  // Include earlier feedback and results so the agent can continue from context.
  const history = await Promise.all(jobs.results.map(async (job) => {
    const rows = await db.prepare(`
      SELECT id, action, button_label AS buttonLabel, user_feedback AS note, status, ticket_outcome AS outcome,
             substr(result, 1, 600) AS result, created_at AS createdAt
      FROM agent_jobs WHERE idea_id = ? AND id < ? ORDER BY id ASC
    `).bind(job.ideaId, job.id).all();
    return rows.results;
  }));
  return Response.json({ jobs: jobs.results.map((job, index) => ({ ...job, history: history[index] })) });
}

export async function POST(request: Request) {
  if (!canUseQueue(request)) return Response.json({ error: "Missing agent key" }, { status: 401 });
  const payload = (await request.json()) as { id?: number; status?: "running" | "done" | "failed"; result?: string; ticketOutcome?: TicketOutcome };
  if (!payload.id || !["running", "done", "failed"].includes(payload.status ?? "")) return Response.json({ error: "Invalid job update" }, { status: 400 });
  if (payload.ticketOutcome && !["completed", "review", "blocked"].includes(payload.ticketOutcome)) return Response.json({ error: "Invalid ticket outcome" }, { status: 400 });
  if (payload.status === "done" && payload.ticketOutcome === "blocked") return Response.json({ error: "A done job cannot be blocked" }, { status: 400 });
  if (payload.status === "failed" && payload.ticketOutcome && payload.ticketOutcome !== "blocked") return Response.json({ error: "A failed job must be blocked" }, { status: 400 });
  const db = await ensureDatabase();
  const job = await db.prepare("SELECT idea_id AS ideaId, action, status FROM agent_jobs WHERE id = ?").bind(payload.id).first<{ ideaId: number; action: string; status: StoredJobStatus }>();
  if (!job) return Response.json({ error: "Job not found" }, { status: 404 });
  if (job.status === payload.status && (job.status === "done" || job.status === "failed")) {
    return Response.json({ ok: true });
  }
  if (!canUpdateJob(job.status, payload.status!)) {
    return Response.json({ error: `Job is already ${job.status}` }, { status: 409 });
  }
  const ticketOutcome = resolveTicketOutcome(payload.status!, payload.ticketOutcome);
  const updates = [
    db.prepare("UPDATE agent_jobs SET status = ?, result = ?, ticket_outcome = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND status = ?")
      .bind(payload.status, payload.result?.slice(0, 20_000) ?? "", ticketOutcome, payload.id, job.status),
  ];
  if ((payload.status === "done" || payload.status === "failed") && job.action !== "no") {
    const ideaStatus = ideaStatusForOutcome(ticketOutcome);
    updates.push(db.prepare(`
      UPDATE ideas SET status = ?
      WHERE id = ? AND status IN ('new', 'working')
        AND NOT EXISTS (
          SELECT 1 FROM agent_jobs newer
          WHERE newer.idea_id = ? AND newer.id > ?
        )
    `).bind(ideaStatus, job.ideaId, job.ideaId, payload.id));
  }
  await db.batch(updates);
  return Response.json({ ok: true, ticketOutcome, ideaStatus: ideaStatusForOutcome(ticketOutcome) });
}

import { ensureDatabase } from "../../../db";
