function isSameOrigin(request: Request) {
  const origin = request.headers.get("origin");
  return !origin || origin === new URL(request.url).origin;
}

function slug(label: string) {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "topic";
}

export async function GET() {
  const db = await ensureDatabase();
  const rows = await db.prepare("SELECT id, label, hint FROM topics ORDER BY position, created_at").all<{ id: string; label: string; hint: string }>();
  return Response.json({ topics: rows.results.map(parseTopicRow) });
}

/** Create or update a topic. Agents may call this too (same loopback rule as cards). */
export async function POST(request: Request) {
  if (!isSameOrigin(request) && request.headers.get("x-radar-local-agent") !== "1") return Response.json({ error: "Blocked origin" }, { status: 403 });
  const payload = (await request.json()) as { id?: string; label?: string; hint?: string };
  const label = payload.label?.trim().slice(0, 40) ?? "";
  if (!label) return Response.json({ error: "A topic needs a label." }, { status: 400 });
  const id = (payload.id?.trim() || slug(label)).slice(0, 40);
  const hint = payload.hint?.trim().slice(0, 120) ?? "";
  const db = await ensureDatabase();
  await db.prepare(`
    INSERT INTO topics (id, label, hint, position)
    VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM topics))
    ON CONFLICT(id) DO UPDATE SET label = excluded.label, hint = excluded.hint
  `).bind(id, label, hint).run();
  return Response.json({ ok: true, id }, { status: 201 });
}

/** Delete a topic. Cards keep their category text; they simply show under All until refiled. */
export async function DELETE(request: Request) {
  if (!isSameOrigin(request) && request.headers.get("x-radar-local-agent") !== "1") return Response.json({ error: "Blocked origin" }, { status: 403 });
  const id = new URL(request.url).searchParams.get("id")?.trim() ?? "";
  if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
  const db = await ensureDatabase();
  await db.prepare("DELETE FROM topics WHERE id = ?").bind(id).run();
  return Response.json({ ok: true });
}

import { ensureDatabase } from "../../../db";
import { parseTopicRow } from "../../../lib/card-cluster";
import { summarizeDecisionMetrics } from "../../../lib/decision-metrics";
import { estimateDecisionTime, type DecisionCardInput } from "../../../lib/decision-time";
import { jobLeaseWindow } from "../../../lib/job-lifecycle";

type IdeaRow = DecisionCardInput & Record<string, unknown>;
type DecisionHistoryRow = DecisionCardInput & {
  decisionAction: string | null;
  decisionSource: string | null;
  activeMs: number | null;
  wallMs: number | null;
  firstActionMs: number | null;
};


const DECISION_HISTORY_SQL = `
    SELECT
      a.decision_action AS decisionAction,
      a.decision_source AS decisionSource,
      a.active_ms AS activeMs,
      a.wall_ms AS wallMs,
      i.agent_context AS agentContext,
      i.decision_estimate_ms AS decisionEstimateMs,
      i.decision_estimate_reason AS decisionEstimateReason,
      (
        SELECT interaction.active_ms FROM card_interactions interaction
        WHERE interaction.idea_id = a.idea_id AND interaction.idea_version = a.idea_version
          AND (a.decided_at IS NULL OR interaction.created_at <= a.decided_at)
          AND interaction.action IN ('do', 'change', 'no', 'open', 'details')
        ORDER BY interaction.id ASC LIMIT 1
      ) AS firstActionMs
    FROM card_attention a
    JOIN ideas i ON i.id = a.idea_id
    WHERE a.decision_source = 'user' AND (
      (a.decided_at IS NOT NULL AND a.decided_at >= datetime('now', '-48 hours'))
      OR (a.decided_at IS NULL AND EXISTS (
        SELECT 1 FROM card_interactions recent_interaction
        WHERE recent_interaction.idea_id = a.idea_id
          AND recent_interaction.idea_version = a.idea_version
          AND recent_interaction.created_at >= datetime('now', '-48 hours')
      ))
    )
  `;

// Cache recent decision metrics across the frequent feed polls.
const DECISION_CACHE_MS = 30_000;
let decisionCache: { at: number; rows: { results: DecisionHistoryRow[] } } | null = null;

async function cachedDecisionRows(db: Awaited<ReturnType<typeof ensureDatabase>>) {
  if (decisionCache && Date.now() - decisionCache.at < DECISION_CACHE_MS) return decisionCache.rows;
  const rows = await db.prepare(DECISION_HISTORY_SQL).all<DecisionHistoryRow>();
  decisionCache = { at: Date.now(), rows };
  return rows;
}

export async function GET(request: Request) {
  const db = await ensureDatabase();
  const leaseWindow = jobLeaseWindow();
  const url = new URL(request.url);
  const requestedView = url.searchParams.get("view");
  const view = requestedView === "working" || requestedView === "done" ? requestedView : "new";
  const requestedCardId = Number(url.searchParams.get("card"));
  const selectedCardId = Number.isInteger(requestedCardId) && requestedCardId > 0 ? requestedCardId : null;
  // `light=1` omits card HTML (the Done list only needs headings); `only=<id>` returns one card.
  const light = url.searchParams.get("light") === "1";
  const requestedOnlyId = Number(url.searchParams.get("only"));
  const onlyId = Number.isInteger(requestedOnlyId) && requestedOnlyId > 0 ? requestedOnlyId : null;
  const context = await db.prepare("SELECT text, created_at AS createdAt FROM contexts ORDER BY id DESC LIMIT 1").first();
  const topicRows = await db.prepare("SELECT id, label, hint FROM topics ORDER BY position, created_at").all<{ id: string; label: string; hint: string }>();
  const ideas = await db.prepare(`
    WITH visible_ideas AS (
      SELECT
        i.id,
        i.version,
        i.project,
        i.category,
        i.headline,
        CASE WHEN ? THEN '' ELSE i.card_html END AS cardHtml,
        i.agent_context AS agentContext,
        i.score,
        i.rise_reach AS riseReach,
        i.rise_impact AS riseImpact,
        i.rise_strategic_fit AS riseStrategicFit,
        i.rise_ease AS riseEase,
        i.decision_estimate_ms AS decisionEstimateMs,
        i.decision_estimate_reason AS decisionEstimateReason,
        i.source_label AS sourceLabel,
        i.source_url AS sourceUrl,
        i.agent_name AS agentName,
        i.dedupe_key AS dedupeKey,
        i.created_at AS createdAt,
        CASE
          WHEN j.status IN ('queued', 'running') THEN 'working'
          ELSE i.status
        END AS status,
        j.id AS jobId,
        CASE
          WHEN j.status = 'running' AND j.updated_at <= datetime('now', ?) THEN 'queued'
          ELSE j.status
        END AS jobStatus,
        j.result AS jobResult,
        j.ticket_outcome AS jobOutcome,
        j.button_label AS jobLabel,
        j.updated_at AS jobUpdatedAt,
        a.active_ms AS decisionActiveMs,
        a.wall_ms AS decisionWallMs,
        a.decision_action AS decisionAction
      FROM ideas i
      LEFT JOIN agent_jobs j ON j.id = (
        SELECT MAX(latest.id) FROM agent_jobs latest WHERE latest.idea_id = i.id
      )
      LEFT JOIN card_attention a ON a.idea_id = i.id AND a.idea_version = i.version AND a.decision_source = 'user'
      WHERE i.card_html != '' AND i.status IN ('new', 'working', 'done')
    )
    SELECT * FROM visible_ideas
    WHERE (status = ? OR (? IS NOT NULL AND id = ?)) AND (? IS NULL OR id = ?)
    ORDER BY score DESC, id DESC
  `).bind(light && !onlyId ? 1 : 0, leaseWindow, view, selectedCardId, selectedCardId, onlyId, onlyId).all<IdeaRow>();
  const laneRows = await db.prepare(`
    WITH latest_jobs AS (
      SELECT job.*
      FROM agent_jobs job
      WHERE NOT EXISTS (
        SELECT 1 FROM agent_jobs newer
        WHERE newer.idea_id = job.idea_id AND newer.id > job.id
      )
    )
    SELECT
      CASE WHEN latest_jobs.status IN ('queued', 'running') THEN 'working' ELSE i.status END AS status,
      COUNT(*) AS total
    FROM ideas i
    LEFT JOIN latest_jobs ON latest_jobs.idea_id = i.id
    WHERE i.card_html != '' AND i.status IN ('new', 'working', 'done')
    GROUP BY 1
  `).all<{ status: string; total: number }>();
  const jobs = await db.prepare(`
    WITH latest_jobs AS (
      SELECT job.*
      FROM agent_jobs job
      WHERE NOT EXISTS (
        SELECT 1 FROM agent_jobs newer
        WHERE newer.idea_id = job.idea_id AND newer.id > job.id
      )
    )
    SELECT
      CASE
        WHEN status = 'running' AND updated_at <= datetime('now', ?) THEN 'queued'
        ELSE status
      END AS status,
      COUNT(*) AS total
    FROM latest_jobs
    WHERE status IN ('queued', 'running')
    GROUP BY 1
  `).bind(leaseWindow).all<{ status: string; total: number }>();
  const completionStats = await db.prepare(`
    WITH latest_jobs AS (
      SELECT job.*
      FROM agent_jobs job
      WHERE NOT EXISTS (
        SELECT 1 FROM agent_jobs newer
        WHERE newer.idea_id = job.idea_id AND newer.id > job.id
      )
    )
    SELECT
      SUM(CASE WHEN i.status = 'done' AND latest_jobs.ticket_outcome = 'completed' THEN 1 ELSE 0 END) AS verified,
      SUM(CASE WHEN i.status = 'done' AND latest_jobs.ticket_outcome = 'completed' THEN CAST(ROUND(i.rise_impact / 2.5) AS INTEGER) ELSE 0 END) AS points,
      SUM(CASE WHEN i.status = 'done' AND latest_jobs.ticket_outcome = 'completed' AND date(latest_jobs.updated_at, '-7 hours') = date('now', '-7 hours') THEN CAST(ROUND(i.rise_impact / 2.5) AS INTEGER) ELSE 0 END) AS pointsToday,
      SUM(CASE WHEN i.status = 'done' AND latest_jobs.ticket_outcome = 'completed' AND date(latest_jobs.updated_at, '-7 hours') = date('now', '-7 hours') THEN 1 ELSE 0 END) AS verifiedToday,
      SUM(CASE WHEN i.status = 'done' AND latest_jobs.ticket_outcome IS NULL THEN 1 ELSE 0 END) AS legacy,
      SUM(CASE WHEN latest_jobs.ticket_outcome = 'review' THEN 1 ELSE 0 END) AS reviewReady,
      SUM(CASE WHEN i.status = 'rejected' THEN 1 ELSE 0 END) AS dismissed
    FROM ideas i
    LEFT JOIN latest_jobs ON latest_jobs.idea_id = i.id
  `).first<{ verified: number | null; legacy: number | null; reviewReady: number | null; dismissed: number | null; points: number | null; pointsToday: number | null; verifiedToday: number | null }>();
  const decisionRows = await cachedDecisionRows(db);
  const enrichedIdeas = ideas.results.map((idea) => {
    const estimate = estimateDecisionTime(idea);
    return {
      ...idea,
      decisionEstimateMs: estimate.estimatedMs,
      decisionEstimateReason: estimate.reason,
    };
  });
  const metricRows = decisionRows.results.map((row) => ({
    ...row,
    estimatedMs: estimateDecisionTime(row).estimatedMs,
  }));
  const jobCounts = Object.fromEntries(jobs.results.map((row) => [row.status, row.total]));
  const laneCounts = Object.fromEntries(laneRows.results.map((row) => [row.status, row.total]));
  return Response.json({
    context,
    topics: topicRows.results.map(parseTopicRow),
    ideas: enrichedIdeas,
    laneCounts: {
      new: laneCounts.new ?? 0,
      working: laneCounts.working ?? 0,
      done: laneCounts.done ?? 0,
    },
    jobs: { queued: jobCounts.queued ?? 0, running: jobCounts.running ?? 0 },
    completionStats: {
      verified: completionStats?.verified ?? 0,
      legacy: completionStats?.legacy ?? 0,
      reviewReady: completionStats?.reviewReady ?? 0,
      dismissed: completionStats?.dismissed ?? 0,
      points: completionStats?.points ?? 0,
      pointsToday: completionStats?.pointsToday ?? 0,
      verifiedToday: completionStats?.verifiedToday ?? 0,
    },
    decisionMetrics: summarizeDecisionMetrics(metricRows),
  });
}

import { ensureDatabase } from "../../../db";
import { clusterForCard, parseTopicRow, type Topic } from "../../../lib/card-cluster";
import { impactPoints } from "../../../lib/rise";
import { PARKED_DECISION_MS } from "../../../lib/decision-metrics";

type DecisionRow = {
  ideaId: number;
  category: string;
  project: string;
  headline: string;
  decisionAction: "do" | "change" | "no";
  decisionLabel: string;
  activeMs: number | null;
  wallMs: number | null;
  decidedAt: string;
  score: number;
};
type CardRow = { id: number; category: string; project: string; headline: string; status: string; score: number; riseImpact: number; outcome: string | null; createdAt: string };

function median(values: number[]) {
  if (!values.length) return null;
  const sorted = values.toSorted((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : Math.round((sorted[mid - 1] + sorted[mid]) / 2);
}

/** Points come from finished work only: a verified completed ticket is worth its RISE score / 10.
 *  Do/Change/Skip are tracked as counts, not points, so the header and the Done list always agree. */
export const POINTS = { do: 3, change: 1, no: -1 } as const;

function emptyBucket() {
  return { do: 0, change: 0, no: 0, parked: 0, likedPoints: 0, medianActiveMs: null as number | null, medianDoMs: null as number | null, activeTimes: [] as number[], doTimes: [] as number[] };
}

export async function GET(request: Request) {
  const db = await ensureDatabase();
  const topicRows = await db.prepare("SELECT id, label, hint FROM topics ORDER BY position, created_at").all<{ id: string; label: string; hint: string }>();
  const topics: Topic[] = topicRows.results.map(parseTopicRow);
  const days = Math.max(1, Math.min(365, Number(new URL(request.url).searchParams.get("days")) || 30));
  const since = `-${days} days`;
  const decisions = await db.prepare(`
    SELECT a.idea_id AS ideaId, i.category, i.project, i.headline, a.decision_action AS decisionAction, a.decision_label AS decisionLabel,
           a.active_ms AS activeMs, a.wall_ms AS wallMs, a.decided_at AS decidedAt, i.score
    FROM card_attention a JOIN ideas i ON i.id = a.idea_id
    WHERE a.decision_source = 'user' AND a.decision_action IN ('do','change','no') AND a.decided_at >= datetime('now', ?)
    ORDER BY a.decided_at DESC
  `).bind(since).all<DecisionRow>();
  const cards = await db.prepare(`
    WITH latest_jobs AS (
      SELECT job.* FROM agent_jobs job
      WHERE NOT EXISTS (SELECT 1 FROM agent_jobs newer WHERE newer.idea_id = job.idea_id AND newer.id > job.id)
    )
    SELECT i.id, i.category, i.project, i.headline, i.status, i.score, i.rise_impact AS riseImpact, latest_jobs.ticket_outcome AS outcome, i.created_at AS createdAt
    FROM ideas i LEFT JOIN latest_jobs ON latest_jobs.idea_id = i.id
    WHERE i.card_html != '' AND i.status IN ('new','working','done','rejected')
  `).all<CardRow>();

  type ClusterBucket = ReturnType<typeof emptyBucket> & { open: number; done: number; rejected: number; donePoints: number };
  const byCluster: Record<string, ClusterBucket> = {};
  const bucketFor = (id: string) => (byCluster[id] ??= { ...emptyBucket(), open: 0, done: 0, rejected: 0, donePoints: 0 });
  for (const topic of topics) bucketFor(topic.id);
  const byDay = new Map<string, { do: number; change: number; no: number; points: number }>();
  const total = emptyBucket();
  for (const row of decisions.results) {
    const bucket = bucketFor(clusterForCard(row, topics));
    const active = Number(row.activeMs ?? 0);
    const wall = Number(row.wallMs ?? 0);
    for (const target of [bucket, total]) {
      target[row.decisionAction] += 1;
      target.likedPoints += POINTS[row.decisionAction];
      if (wall > PARKED_DECISION_MS) target.parked += 1;
      if (Number.isFinite(active) && active >= 0) {
        target.activeTimes.push(active);
        if (row.decisionAction === "do") target.doTimes.push(active);
      }
    }
    const day = row.decidedAt.slice(0, 10);
    const d = byDay.get(day) ?? { do: 0, change: 0, no: 0, points: 0 };
    d[row.decisionAction] += 1;
    d.points += POINTS[row.decisionAction];
    byDay.set(day, d);
  }
  let donePoints = 0;
  for (const card of cards.results) {
    const bucket = bucketFor(clusterForCard(card, topics));
    if (card.status === "done") {
      bucket.done += 1;
      if (card.outcome === "completed") {
        const pts = impactPoints(card);
        bucket.donePoints += pts;
        donePoints += pts;
      }
    } else if (card.status === "rejected") bucket.rejected += 1;
    else bucket.open += 1;
  }
  const finish = (b: ReturnType<typeof emptyBucket>) => {
    const { activeTimes, doTimes, ...rest } = b;
    return { ...rest, medianActiveMs: median(activeTimes), medianDoMs: median(doTimes), decided: b.do + b.change + b.no, doRate: b.do + b.change + b.no ? Math.round((100 * b.do) / (b.do + b.change + b.no)) : null };
  };
  const clusters = topics.map((c) => ({ id: c.id, label: c.label, hint: c.hint, ...finish(byCluster[c.id]), open: byCluster[c.id].open, done: byCluster[c.id].done, rejected: byCluster[c.id].rejected, donePoints: byCluster[c.id].donePoints }));
  // Decision rate by category over the window (at least three decisions).
  const byCategory = new Map<string, { do: number; change: number; no: number }>();
  for (const row of decisions.results) {
    const key = row.category.trim() || "Other";
    const c = byCategory.get(key) ?? { do: 0, change: 0, no: 0 };
    c[row.decisionAction] += 1;
    byCategory.set(key, c);
  }
  const categories = [...byCategory.entries()]
    .map(([name, c]) => ({ name, ...c, decided: c.do + c.change + c.no, doRate: Math.round((100 * c.do) / (c.do + c.change + c.no)) }))
    .filter((c) => c.decided >= 3)
    .toSorted((a, b) => b.doRate - a.doRate || b.decided - a.decided);
  const recent = decisions.results.slice(0, 40).map((r) => ({ ideaId: r.ideaId, headline: r.headline, action: r.decisionAction, activeMs: r.activeMs, decidedAt: r.decidedAt, cluster: clusterForCard(r, topics) }));
  return Response.json({
    days,
    total: { ...finish(total), likedPoints: total.likedPoints, donePoints, points: donePoints },
    clusters,
    categories,
    days_series: [...byDay.entries()].toSorted(([a], [b]) => (a < b ? -1 : 1)).map(([day, d]) => ({ day, ...d })),
    recent,
  });
}

import { ensureDatabase } from "../../../../db";

type AttentionEvent = {
  id?: number;
  version?: number;
  event?: "view" | "active" | "interaction";
  activeMs?: number;
  action?: string;
  label?: string;
};

const interactionActions = new Set(["open", "details", "next", "back", "lane", "new_task", "context", "update"]);

export async function POST(request: Request) {
  const origin = request.headers.get("origin");
  if (origin && origin !== new URL(request.url).origin) {
    return Response.json({ error: "Blocked origin" }, { status: 403 });
  }

  const payload = (await request.json()) as AttentionEvent;
  const id = Number(payload.id);
  const version = Number(payload.version);
  if (!Number.isInteger(id) || id < 1 || !Number.isInteger(version) || version < 1) {
    return Response.json({ error: "Invalid card" }, { status: 400 });
  }

  const db = await ensureDatabase();
  if (payload.event === "view") {
    await db.prepare(`
      INSERT INTO card_attention (idea_id, idea_version, view_count)
      SELECT id, version, 1 FROM ideas WHERE id = ? AND version = ?
      ON CONFLICT(idea_id, idea_version) DO UPDATE SET
        view_count = card_attention.view_count + 1,
        last_seen_at = CURRENT_TIMESTAMP
    `).bind(id, version).run();
    return Response.json({ ok: true });
  }

  if (payload.event === "active") {
    const activeMs = Math.max(0, Math.min(15_000, Math.round(Number(payload.activeMs ?? 0))));
    if (!activeMs) return Response.json({ ok: true });
    await db.prepare(`
      INSERT INTO card_attention (idea_id, idea_version, active_ms, view_count)
      SELECT id, version, ?, 0 FROM ideas WHERE id = ? AND version = ?
      ON CONFLICT(idea_id, idea_version) DO UPDATE SET
        active_ms = card_attention.active_ms + excluded.active_ms,
        last_seen_at = CURRENT_TIMESTAMP
    `).bind(activeMs, id, version).run();
    return Response.json({ ok: true });
  }

  if (payload.event === "interaction") {
    const action = payload.action?.trim().slice(0, 40) ?? "";
    const label = payload.label?.trim().slice(0, 120) ?? "";
    if (!interactionActions.has(action)) return Response.json({ error: "Invalid interaction" }, { status: 400 });
    const activeMs = Math.max(0, Math.min(15_000, Math.round(Number(payload.activeMs ?? 0))));
    await db.batch([
      db.prepare(`
        INSERT INTO card_attention (idea_id, idea_version, active_ms, view_count)
        SELECT id, version, ?, 0 FROM ideas WHERE id = ? AND version = ?
        ON CONFLICT(idea_id, idea_version) DO UPDATE SET
          active_ms = card_attention.active_ms + excluded.active_ms,
          last_seen_at = CURRENT_TIMESTAMP
      `).bind(activeMs, id, version),
      db.prepare(`
        INSERT INTO card_interactions (idea_id, idea_version, action, label, active_ms, wall_ms)
        SELECT idea_id, idea_version, ?, ?, active_ms,
          MAX(0, CAST((julianday(CURRENT_TIMESTAMP) - julianday(first_seen_at)) * 86400000 AS INTEGER))
        FROM card_attention WHERE idea_id = ? AND idea_version = ?
      `).bind(action, label, id, version),
    ]);
    return Response.json({ ok: true });
  }

  return Response.json({ error: "Invalid attention event" }, { status: 400 });
}

